-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        company_source_system,
        company_identity_key,
        company_normalised_name,
        company_lei,
        company_external_id,
        company_business_key,
        company_record_id,
        company_source_id,
        company_fund_source_id,
        company_name,
        company_sector,
        company_sub_sector,
        company_country,
        company_status,
        company_reported_on,
        violation_00,
        violation_01
    from {{ ref("investment__portfolio_company_vault__checked_post") }}
),
violations as (
    select
        'company_business_key_not_null' as rule_name,
        company_source_system,
        company_identity_key,
        company_normalised_name,
        company_lei,
        company_external_id,
        company_business_key,
        company_record_id,
        company_source_id,
        company_fund_source_id,
        company_name,
        company_sector,
        company_sub_sector,
        company_country,
        company_status,
        company_reported_on
    from quarantined
    where violation_00

    union all

    select
        'company_business_key_unique' as rule_name,
        company_source_system,
        company_identity_key,
        company_normalised_name,
        company_lei,
        company_external_id,
        company_business_key,
        company_record_id,
        company_source_id,
        company_fund_source_id,
        company_name,
        company_sector,
        company_sub_sector,
        company_country,
        company_status,
        company_reported_on
    from quarantined
    where violation_01
)

select
    rule_name,
    company_source_system,
    company_identity_key,
    company_normalised_name,
    company_lei,
    company_external_id,
    company_business_key,
    company_record_id,
    company_source_id,
    company_fund_source_id,
    company_name,
    company_sector,
    company_sub_sector,
    company_country,
    company_status,
    company_reported_on
from violations
